typedef int (*PluginCallback)(int input_data);

struct PluginHost {
    PluginCallback handler;
};

// Concrete implementation (the plugin's payload)
int Plugin_A(int data) {
    return data * data;
}

// Host registration function
void Host_Register(struct PluginHost *h, PluginCallback cb) {
    h->handler = cb;
}

// Host execution function
int Host_Execute(struct PluginHost *h, int input) {
    if (h->handler) {
        return h->handler(input); // Dynamic invocation
    }
    return 0;
}
